(()=>{"use strict";self.addEventListener("push",t=>{try{let i=t.data?.json(),e=i?.title||"Habit Tracker",n=i?.body||"Check your progress";t.waitUntil(self.registration.showNotification(e,{body:n,icon:"/pwa-icons/icon-192",badge:"/pwa-icons/icon-192",data:{url:i?.url||"/"}}))}catch(t){console.error("Error handling push event:",t)}}),self.addEventListener("notificationclick",t=>{t.notification.close();let i=t.notification.data?.url||"/";t.waitUntil(self.clients.matchAll({type:"window",includeUncontrolled:!0}).then(t=>{for(let e of t)if(e.url===i||e.url.startsWith(self.location.origin)&&i.startsWith("/"))return e.focus();if(self.clients.openWindow)return self.clients.openWindow(i)}))})})();